import os

def load_config(path):
    """Reads configuration from a text file."""
    if not os.path.exists(path):
        return None
    try:
        with open(path, 'r', encoding='utf-8') as f:
            return f.read()
    except Exception as e:
        print(f"Error: {e}")
        return None

if __name__ == "__main__":
    config = load_config("settings.conf")
    print(config)

